package selfcheck
import("testing";"task143-batchreactor/internal/forecast";"task143-batchreactor/internal/model";"task143-batchreactor/internal/report")
func TestBug09_AbortedBatchIsTerminalEverywhere(t *testing.T){if !model.BatchAborted.IsTerminal(){t.Fatal("aborted not terminal")};f:=forecast.Build(forecast.Input{Batch:model.Batch{ID:"b",Status:model.BatchAborted,EndedAt:5},Recipe:exothermicRecipe(),Reactor:safeReactor(),Result:&model.SafetyResult{Verdict:model.VerdictSafe,PeakTemp:400,Conversion:.95,TMRSeconds:999999},Now:10});if f.Phase!=model.ForecastTerminal||f.EstimatedFinish!=5||f.NextAction!="review abort cause and return reactor to a safe state"{t.Fatalf("aborted forecast=%+v",f)};a:=report.Build(report.Input{Batches:[]model.Batch{{ID:"b",Status:model.BatchAborted}},Now:1});if a.AbortedCount!=1||a.ActiveCount!=0{t.Fatalf("aborted/active=%d/%d",a.AbortedCount,a.ActiveCount)}}
